import{_ as s,C as t,o as e,c as h,j as a,E as o,a as l,a2 as r}from"./chunks/framework.C21TwvGF.js";const T=JSON.parse(`{"title":"1-dars (Mentor). Game Design faniga kirish: Tushunchasi, ahamiyati va dasturiy vositalar","description":"","frontmatter":{"title":"1-dars (Mentor). Game Design faniga kirish: Tushunchasi, ahamiyati va dasturiy vositalar","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":1,"link":"/mentor/9-sinf-game/hafta-01/"},"g":1,"title":"Game Design faniga kirish: Tushunchasi, ahamiyati va dasturiy vositalar","lead":"O'yin yaratish — bu shunchaki kod yozish yoki rasm chizish emas. Bu insonlar his qiladigan butun boshli yangi olam va unutilmas sarguzashtni barpo etish san'atidir!","slide":"/slaydlar/9-sinf-game/hafta-01/dars-1.html","test":"/slaydlar/9-sinf-game/hafta-01/dars-1-test.html","student_link":"/9-sinf-game/hafta-01/dars-1","tabs":[{"g":1,"link":"/mentor/9-sinf-game/hafta-01/dars-1","current":true},{"g":2,"link":"/mentor/9-sinf-game/hafta-01/dars-2","current":false},{"g":3,"link":"/mentor/9-sinf-game/hafta-01/dars-3","current":false}],"prev":null,"next":{"g":2,"title":"O‘yinlarning tarixi va janrlari: O'yin evolyutsiyasi, janrlar tasnifi va madaniy ta'siri","link":"/mentor/9-sinf-game/hafta-01/dars-2"}}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-01/dars-1.md","filePath":"mentor/9-sinf-game/hafta-01/dars-1.md"}`),y={name:"mentor/9-sinf-game/hafta-01/dars-1.md"},m={class:"blk"},d={id:"dars-rejasi",tabindex:"-1"},g={class:"blk"},u={id:"mentor-konspekti",tabindex:"-1"},k={class:"blk"},q={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},v={class:"blk"},b={id:"tezkor-nazorat-savollari",tabindex:"-1"},c={class:"blk"},f={id:"uyga-vazifa",tabindex:"-1"};function p(z,i,_,j,x,D){const n=t("Icon");return e(),h("div",null,[a("div",m,[a("h2",d,[o(n,{name:"file-text"}),i[0]||(i[0]=l(" Dars rejasi ",-1)),i[1]||(i[1]=a("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),i[2]||(i[2]=r("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga Game Design (o&#39;yin dizayni) sohasi, uning zamonaviy raqamli madaniyat va iqtisodiyotdagi o&#39;rni, Game Designer kasbiy roli va vazifalari, o&#39;yin dizaynining 5 ta asosiy komponenti (Gameplay, Level Design, Narratsiya, UI va UX) hamda zamonaviy o&#39;yin dvijoklari (Unity, Unreal Engine, Godot) va konstruktorlari haqida chuqur nazariy va amaliy tushuncha berish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar o&#39;yin dizayneri faqat dasturchi yoki rassom emas, balki butun o&#39;yin tajribasini yaratuvchi &quot;rejissyor&quot; ekanini anglaydi; o&#39;yinning 5 komponentini mustaqil tahlil qila oladi; o&#39;z g&#39;oyasiga mos o&#39;yin dvijogini tanlay oladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>Kirish va yo&#39;nalish bilan tanishuv: 10 daqiqa</li><li>Yangi mavzu: Game Design nima va uning ahamiyati: 20 daqiqa</li><li>Game Designer roli va 5 ta asosiy komponent: 25 daqiqa</li><li>Dasturiy vositalar (Dvijoklar va konstruktorlar) tahlili: 15 daqiqa</li><li>Tezkor savol-javob va xulosa: 10 daqiqa</li></ul></li></ul><hr>",2))]),a("div",g,[a("h2",u,[o(n,{name:"file-text"}),i[3]||(i[3]=l(" Mentor konspekti ",-1)),i[4]||(i[4]=a("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),i[5]||(i[5]=r('<h3 id="_1-game-design-tushunchasi-va-uning-ahamiyati" tabindex="-1">1. Game Design tushunchasi va uning ahamiyati <a class="header-anchor" href="#_1-game-design-tushunchasi-va-uning-ahamiyati" aria-label="Permalink to &quot;1. Game Design tushunchasi va uning ahamiyati&quot;">​</a></h3><ul><li><strong>Game Design (o&#39;yin dizayni)</strong> — bu o&#39;yinlarni g&#39;oyadan boshlab to yakuniy ko&#39;rinishigacha rejalashtirish, loyihalash va shakllantirish jarayonidir. U o&#39;yindagi qoidalar, maqsadlar, o&#39;yinchi harakatlari, atrof-muhit, grafika, ovozlar, hikoya va umumiy foydalanuvchi tajribasini ishlab chiqishni qamrab oladi.</li><li><strong>Ahamiyati:</strong><ul><li><em>Ta&#39;limiy ahamiyati:</em> Simulyatsiya va ta&#39;limiy o&#39;yinlar orqali fizika, tarix, biologiya kabi murakkab fanlarni interaktiv o&#39;zlashtirish.</li><li><em>Ijodiy fikrlash:</em> Yangi virtual olamlar, noan&#39;anaviy personajlar va qiziqarli mexanikalarni yaratish.</li><li><em>Iqtisodiy ahamiyati:</em> Dunyoda o&#39;yin industriyasi (GameDev) kino va musiqa sohalarining umumiy daromadidan ham oshib ketgan (yillik 200+ milliard dollar).</li><li><em>Psixologik va ijtimoiy:</em> Motivatsiya, jamoaviy hamkorlik va strategik qaror qabul qilish ko&#39;nikmalarini shakllantirish.</li></ul></li></ul><h3 id="_2-game-designer-o-yin-dizayneri-kim" tabindex="-1">2. Game Designer (O&#39;yin dizayneri) kim? <a class="header-anchor" href="#_2-game-designer-o-yin-dizayneri-kim" aria-label="Permalink to &quot;2. Game Designer (O&#39;yin dizayneri) kim?&quot;">​</a></h3><p>Game Designer — bu video o&#39;yinning kontseptsiyasi, mexanikasi va qoidalarini ishlab chiqish uchun mas&#39;ul bo&#39;lgan asosiy mutaxassis.</p><ul><li>Uni o&#39;yinning <strong>&quot;bosh rejissyori&quot;</strong> deb atash mumkin.</li><li><strong>Asosiy vazifalari:</strong><ol><li><em>Kontseptsiya va qoidalar:</em> O&#39;yin nima haqida, unda qanday qoidalar mavjudligini belgilash.</li><li><em>Gameplay loyihalash:</em> O&#39;yinchi har soniyada nima qiladi va qanday his qiladi?</li><li><em>O&#39;yin balansi (Balancing):</em> O&#39;yin haddan tashqari oson bo&#39;lib zeriktirmasligi yoki o&#39;ta qiyin bo&#39;lib tushkunlikka tushirmasligi kerak.</li><li><em>Jamoani muvofiqlashtirish:</em> Dasturchilar, 2D/3D rassomlar, kompozitorlar va ssenaristlar ishini yagona maqsad sari birlashtirish.</li></ol></li></ul><h3 id="_3-o-yin-dizaynining-5-ta-asosiy-komponenti" tabindex="-1">3. O&#39;yin dizaynining 5 ta asosiy komponenti <a class="header-anchor" href="#_3-o-yin-dizaynining-5-ta-asosiy-komponenti" aria-label="Permalink to &quot;3. O&#39;yin dizaynining 5 ta asosiy komponenti&quot;">​</a></h3><p>Robert Zubek va Kris Krouford tasnifiga ko&#39;ra:</p><ol><li><strong>Gameplay (O&#39;yin jarayoni):</strong> O&#39;yinchining faol harakatlari — yugurish, sakrash, jang qilish, resurs yig&#39;ish, jumboq yechish.</li><li><strong>Level Design (Bosqich dizayni):</strong> O&#39;yin xaritalari, labirintlar, to&#39;siqlar va dushmanlarning joylashuv arxitekturasi.</li><li><strong>Narratsiya (Hikoya va syujet):</strong> Voqealar rivoji, qahramonlar xarakteri, dialoglar va o&#39;yin olami tarixi (Lore).</li><li><strong>UI (User Interface):</strong> O&#39;yinchi ekranda ko&#39;radigan barcha boshqaruv tugmalari, menyular va ko&#39;rsatkichlar.</li><li><strong>UX (User Experience):</strong> O&#39;yinchi o&#39;yin davomida oladigan umumiy hissiyot, qoniqish va boshqaruv qulayligi.</li></ol><h3 id="_4-dasturiy-vositalar-o-yin-dvijoklari-va-konstruktorlar" tabindex="-1">4. Dasturiy vositalar: O&#39;yin dvijoklari va konstruktorlar <a class="header-anchor" href="#_4-dasturiy-vositalar-o-yin-dvijoklari-va-konstruktorlar" aria-label="Permalink to &quot;4. Dasturiy vositalar: O&#39;yin dvijoklari va konstruktorlar&quot;">​</a></h3><ul><li><strong>Game Engine (O&#39;yin dvijogi):</strong> Noldan hamma narsani dasturlamasdan, tayyor fizika, render, animatsiya va audio tizimlaridan foydalanib o&#39;yin yaratish muhiti. <ul><li><strong>Unity:</strong> Dunyodagi eng ommabop universal dvijok. 2D va 3D mobil, kompyuter va konsol o&#39;yinlari uchun ideal (C# tili).</li><li><strong>Unreal Engine:</strong> Eng yuqori sifatli fotorealistik grafika (AAA loyihalar) dvijogi (C++ va Blueprints vizual skripti).</li><li><strong>Godot Engine:</strong> Bepul, ochiq kodli (open-source), juda yengil va tezkor dvijok (GDScript, C#).</li></ul></li><li><strong>Konstruktorlar (Boshlovchilar uchun):</strong><ul><li><strong>Construct 3:</strong> Kod yozmasdan, brauzerda bloklar va hodisalar (Event Sheet) orqali 2D o&#39;yinlar yaratish.</li><li><strong>GameMaker Studio:</strong> 2D platformerlar va pikselli o&#39;yinlar yaratishda yetakchi (GML tili).</li><li><strong>RPG Maker:</strong> Maxsus 2D rolli (RPG) o&#39;yinlar yaratish vositasi.</li></ul></li></ul><hr>',11))]),a("div",k,[a("h2",q,[o(n,{name:"file-text"}),i[6]||(i[6]=l(" Amaliy topshiriqlar va yechimlar ",-1)),i[7]||(i[7]=a("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),i[8]||(i[8]=r('<h3 id="_1-topshiriq-mashhur-o-yinning-5-komponentini-tahlil-qilish-oson" tabindex="-1">1-topshiriq. Mashhur o&#39;yinning 5 komponentini tahlil qilish (oson) <a class="header-anchor" href="#_1-topshiriq-mashhur-o-yinning-5-komponentini-tahlil-qilish-oson" aria-label="Permalink to &quot;1-topshiriq. Mashhur o&#39;yinning 5 komponentini tahlil qilish (oson)&quot;">​</a></h3><p>O&#39;zingizga ma&#39;lum bo&#39;lgan bitta mashhur o&#39;yinni (masalan, <em>Subway Surfers</em> yoki <em>Minecraft</em>) o&#39;yin dizaynining 5 ta asosiy komponenti bo&#39;yicha tahlil qiling.</p><p><strong>Yechim:</strong><em>Subway Surfers</em> misolida:</p><ol><li><strong>Gameplay:</strong> Poezdlar ustida chopish, to&#39;siqlardan chapga-o&#39;ngga qochish, sakrash, tangalar va kuchaytirgichlar (jetpack, magnet) yig&#39;ish.</li><li><strong>Level Design:</strong> Cheksiz davom etuvchi 3 ta temir yo&#39;l izi, dinamik harakatlanuvchi vagonlar, tunnellar va to&#39;siqlar joylashuvi.</li><li><strong>Narratsiya:</strong> Grafiti chizayotgan yosh qahramonning qattiqqo&#39;l nazoratchi va uning itidan qochishi haqidagi sodda, ammo jozibali motivatsiya.</li><li><strong>UI:</strong> Ekranning tepasidagi tangalar soni, masofa hisoblagichi, multiplikator ko&#39;rsatkichi va pauza tugmasi.</li><li><strong>UX:</strong> Bir barmog&#39;ingiz bilan boshqariladigan silliq siljitish (swipe) mexanikasi, yorqin ranglar va dinamik musiqa orqali hayajon uyg&#39;otishi.</li></ol><h3 id="_2-topshiriq-loyiha-talabiga-qarab-o-yin-dvijogini-tanlash-o-rta" tabindex="-1">2-topshiriq. Loyiha talabiga qarab o&#39;yin dvijogini tanlash (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-loyiha-talabiga-qarab-o-yin-dvijogini-tanlash-o-rta" aria-label="Permalink to &quot;2-topshiriq. Loyiha talabiga qarab o&#39;yin dvijogini tanlash (o&#39;rta)&quot;">​</a></h3><p>Mustaqil ishlab chiquvchi (Indie developer) jamoasi quyidagi o&#39;yinni yaratmoqchi: &quot;2D uslubidagi mobil boshqotirma o&#39;yini, jamoada dasturchi yo&#39;q, hamma narsani 2 oy ichida vizual tarzda yaratib, Android&#39;ga yuklash kerak.&quot; Qaysi dasturiy vosita eng maqbul hisoblanadi va nima uchun?</p><p><strong>Yechim:</strong><strong>Construct 3</strong> (yoki GameMaker). <em>Sababi:</em></p><ol><li>Dasturlash tillarini (C#, C++) bilish talab etilmaydi — voqealar mantiqiy bloklar (Event System) orqali yig&#39;iladi.</li><li>2D grafikaga to&#39;liq ixtisoslashgan va mobil ekranlarga juda tez moslashadi.</li><li>Ishlab chiqish muddati juda qisqa (rapid prototyping).</li></ol><h3 id="_3-topshiriq-o-yin-mexanikasi-va-balansi-loyihasi-qiyin" tabindex="-1">3-topshiriq. O&#39;yin mexanikasi va balansi loyihasi (qiyin) <a class="header-anchor" href="#_3-topshiriq-o-yin-mexanikasi-va-balansi-loyihasi-qiyin" aria-label="Permalink to &quot;3-topshiriq. O&#39;yin mexanikasi va balansi loyihasi (qiyin)&quot;">​</a></h3><p>Tasavvur qiling, siz yangi jangovar o&#39;yinda o&#39;yinchiga &quot;Sehrli qalqon&quot; (Magic Shield) qobiliyatini berdingiz. Ushbu qalqon barcha zarbalarni 100% qaytaradi. Ushbu qobiliyat o&#39;yin balansini buzmasligi uchun qanday cheklovlar va muvozanat mexanizmlari kiritishingiz kerak?</p><p><strong>Yechim:</strong> Agar qalqon cheksiz ishlasa, o&#39;yinchi yengilmas bo&#39;lib qoladi va o&#39;yin zerikarli bo&#39;lib qoladi (Balans buziladi). Muvozanat uchun:</p><ol><li><strong>Cooldown (Qayta yuklanish vaqti):</strong> Qalqon faqat 3 soniya ishlaydi, qayta ishlatish uchun 15 soniya kutish kerak.</li><li><strong>Energiya/Mana sarfi:</strong> Qalqon har soniyada katta miqdorda energiya (mana) sarflaydi.</li><li><strong>Qisman o&#39;tkazuvchanlik:</strong> 100% o&#39;rniga faqat 70% zarbani yutadi, qolgan 30% esa o&#39;yinchiga tegadi.</li><li><strong>Qarshi qurol (Counter-play):</strong> Raqiblarda qalqonni bir zarbada sindiruvchi maxsus og&#39;ir qurol bo&#39;lishi lozim.</li></ol><hr>',13))]),a("div",v,[a("h2",b,[o(n,{name:"file-text"}),i[9]||(i[9]=l(" Tezkor nazorat savollari ",-1)),i[10]||(i[10]=a("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),i[11]||(i[11]=r("<ol><li>Game Designer va Game Programmer o&#39;rtasidagi asosiy farq nimada? <ul><li><em>Javob:</em> Designer o&#39;yinning qoidalari, his-tuyg&#39;usi va umumiy tizimini o&#39;ylab topadi; Programmer esa ushbu g&#39;oyalarni dasturiy kodga aylantiradi.</li></ul></li><li>O&#39;yin dizaynining qaysi komponenti o&#39;yinchi ekranda ko&#39;radigan menyu va sog&#39;lik panelini o&#39;z ichiga oladi? <ul><li><em>Javob:</em> UI (User Interface).</li></ul></li><li>Ochiq kodli va bepul zamonaviy o&#39;yin dvijogi qaysi? <ul><li><em>Javob:</em> Godot Engine.</li></ul></li><li>Nima uchun o&#39;yin juda oson bo&#39;lishi xavfli? <ul><li><em>Javob:</em> Oson o&#39;yin o&#39;yinchiga hech qanday qiyinchilik (challenge) taqdim etmaydi va tezda zerikarli bo&#39;lib qoladi.</li></ul></li></ol><hr>",2))]),a("div",c,[a("h2",f,[o(n,{name:"house"}),i[12]||(i[12]=l(" Uyga vazifa ",-1)),i[13]||(i[13]=a("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),i[14]||(i[14]=a("p",null,"O'zingiz yoqtirgan bitta mobil yoki kompyuter o'yinini tanlang. Daftaringizda:",-1)),i[15]||(i[15]=a("ol",null,[a("li",null,"O'yin nomi va yaratuvchi studiyasini yozing;"),a("li",null,"Ushbu o'yinda Game Designer qanday asosiy maqsad qo'yganini (o'yinchi nima qilishi kerakligini) 3 ta jumlada tasvirlang;"),a("li",null,"O'yindagi 3 ta ijobiy va 1 ta salbiy dizayn jihatini (kamchiligini) ko'rsating.")],-1))])])}const O=s(y,[["render",p]]);export{T as __pageData,O as default};
